import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class CommentsConfigurationTest {

    @Test
    public void comments_configuration_emptyMap() {
        Map<String, List<String>> comments = Collections.emptyMap();
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path", "");
        assertNull(configuration.getAllComments());
    }

    @Test
    public void comments_configuration_singleLineComment() {
        Map<String, List<String>> comments = Collections.singletonMap("path", Collections.singletonList(""));
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path", "/*");
        assertEquals(Collections.emptyList(), configuration.getAllComments().values());
    }

    @Test
    public void comments_configuration_multilineComment() {
        Map<String, List<String>> comments = Collections.singletonMap("path", Collections.singletonList(""));
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path", "/*\nHello\nWorld*/");
        assertEquals(Collections.singletonList(List.of("", null)), configuration.getAllComments().values());
    }

    @Test
    public void comments_configuration_multipleLines() {
